    domino_rules_title: "Domino Rules",
    domino_rules_intro: "A quick reference for how PaperGames plays the classic draw game with a double-six set - useful if you're rusty, or learning.",
    domino_rules_basics_title: "The basic idea",
    domino_term_set: "The tiles",
    domino_rules_set: "A double-six set has 28 tiles. Each tile has two halves showing 0 to 6 pips, and every combination appears exactly once - from 0-0 to 6-6. A tile with the same number on both halves is a double.",
